mapper.insert:
INSERT
  INTO icam02_data
SELECT f_create_batchseq()
     , #{p.icamCompanyCode}
     , #{p.icamDate}
     , #{p.fundCode}
     , #{p.fundName}
     , #{p.itemCode}
     , #{p.itemName}
     , #{p.seq}
     , #{p.infoCode}
     , #{p.trCode}
     , #{p.assetCode}
     , #{p.assetName}
     , #{p.tgtDate}
     , #{p.tgtAmt}
     , #{p.tgtStdDate}
     , #{p.note}
     , ( SELECT icam01_ics_class_tree_id
           FROM icam01_data_info
          WHERE icam01_info_cd = #{p.infoCode}
            AND icam01_tr_cd   = #{p.trCode} )
     , null
     , f_sysdate()
     , #{p.creater}
     , 'false'
     , null

mapper.delete:
DELETE
  FROM icam03_fund
 WHERE icam03_icam_company_cd = #{p.icamCompanyCode}
   AND icam03_std_date        = #{p.stdDate}
   AND icam03_fund_cd         = #{p.fundCode}

